      "relation": {"op": "same_object", "left": "cp2", "right": "e_enum"}
    },
    "sink": {
      "file": "snmplib/snmp_enum.c",
      "function": "se_read_conf",
      "line": 124,
      "operands": ["cp2", "strdup(cp2)"],
      "relation": {"op": "gt", "left": "cp2", "right": "e_enum"}
    },
    "propagation": [
      {
